     [("A", "Classical Unilineal Evolutionism (Tylor, Morgan - 1870s)"),
      ("B", "Historical Particularism & Diffusionism (Boas, Wissler, Schmidt - 1900s–1920s)"),
      ("C", "British Functionalism & Structural-Functionalism (Malinowski, Radcliffe-Brown - 1920s–1940s)"),
      ("D", "French Structuralism & Interpretive Anthropology (Lévi-Strauss, Geertz - 1950s–1970s)")],
     "A, B, C, D",
